final class ContextSignedWitnessPlanMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 static Snapshot bind(boolean local,String text)throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);if(!text.isEmpty())require(m.compile(text,null,false),"actual row compilation");ContextProductionInventory v=ContextProductionInventory.inspect(m,UUID.randomUUID(),1,local,Collections.emptyList(),1000);ContextProductionNativeBinding.Result r=ContextProductionNativeBinding.bind(m,v,WORK,500000);require(r.bound,r.reason);return r.snapshot;}
 static Plan plan(Snapshot x,List<Snapshot> f){ContextSignedWitnessPlan.Result r=ContextSignedWitnessPlan.build(x,f,64,WORK);require(r.planned&&r.output!=null,r.phase+": "+r.reason);return r.output;}
 static ContextSignedWitnessPlanAudit.Receipt audit(Plan p,Snapshot x,List<Snapshot> f){ContextSignedWitnessPlanAudit.Inspection r=ContextSignedWitnessPlanAudit.inspect(p,x,f,64,WORK);require(r.audited&&r.output!=null,r.phase+": "+r.reason);ContextSignedWitnessPlanAudit.check(r.output,x,f,64,WORK);require(true,"fresh independent replay of sealed receipt");return r.output;}
 static void positive()throws Exception{
  Snapshot x=bind(true,"!$u local(u,1)&&~off(u,1); !~raw(2); !@v a(v)->b(v);"),a=bind(false,"!$u seed(u,1)&&~blocked(u,1); !p(1);"),b=bind(false,"!$u seed(u,1)&&flag(u,1); !@u seed(u,1)->ready(u,1);");Set<Source> expected=new HashSet<>();for(Snapshot s:Arrays.asList(x,a,b))for(ContextProductionNativeBinding.Entry e:s.primary)expected.add(e.source);
  for(boolean grouped:new boolean[]{false,true})for(boolean reverse:new boolean[]{false,true}){List<Snapshot> members=reverse?Arrays.asList(b,a):Arrays.asList(a,b);List<Snapshot> foreign=grouped?Collections.singletonList(ContextProductionNativeBinding.trusted("signed-plan",members,WORK)):members;Plan p=plan(x,foreign);audit(p,x,foreign);require(p.rows.size()==7&&p.signedRows==2,"all seven whole rows and both signed bundles accounted");Set<Source> actual=new HashSet<>();Set<Origin> origins=new HashSet<>();int atoms=0,negative=0,opaque=0;for(Row row:p.rows){actual.add(row.original.source);if(row.kind==Kind.OPAQUE_CLAUSES){++opaque;require(row.seeds.isEmpty()&&row.clauses.size()==row.original.clauses.size(),"ordinary clauses remain opaque whole-row records");}for(Seed seed:row.seeds){++atoms;if(!seed.positive)++negative;require(seed.proof.depth==0&&seed.proof.sources.equals(Collections.singleton(row.original.source)),"original exact Source, no clause Source minting");for(Term t:seed.arguments)if(t.origin!=null){require(t.origin.source.equals(row.original.source)&&t.origin.binder==0&&t.value==null,"Source-owned binder0 across literal signs");origins.add(t.origin);}else require(t.value!=null,"ordinary value stays ordinary");}if(grouped&&!row.original.source.localX)require(row.cut.members.size()==2&&row.cut.members.contains(row.member)&&row.member.inventory.context.equals(row.original.source.context),"full physical member retained under logical trusted cut");}
   require(actual.equals(expected)&&opaque==4&&atoms==6&&negative==2&&origins.size()==3,"exact whole Sources, signs, opaque rows and distinct same-number Origins");require(!ContextUniversalNativeRows.inspect(x,foreign.get(0),64,WORK).withinShape,"new data plan does NOT broaden old whole-row classifier");boolean immutable=false;try{p.rows.clear();}catch(UnsupportedOperationException ok){immutable=true;}require(immutable,"plan rows immutable");}
  Snapshot multiple=bind(true,"!$u $v left(u,1)&&~right(v,1);");Plan two=plan(multiple,Collections.emptyList());audit(two,multiple,Collections.emptyList());require(two.rows.get(0).witnesses==2&&two.rows.get(0).seeds.get(0).arguments.get(0).origin.binder==0&&two.rows.get(0).seeds.get(1).arguments.get(0).origin.binder==1&&!two.rows.get(0).seeds.get(0).arguments.get(0).origin.equals(two.rows.get(0).seeds.get(1).arguments.get(0).origin),"different binders in ONE signed whole Source remain distinct");
  Snapshot empty=bind(true,"");Plan p=plan(empty,Collections.emptyList());audit(p,empty,Collections.emptyList());require(p.rows.isEmpty()&&p.signedRows==0,"empty data plan has no invented witness rows or inference status");
  System.out.println("SIGNED_WITNESS_PLAN orders=4 exactWholeRows=true polarityAndOrigins=true trustedPhysicalMembers=true opaqueClauses=true independentAudit=true oldEligibilityUnchanged=true");
 }
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}require(failed,why);}
 static void bad(Plan p,Snapshot x,List<Snapshot> f,String why){ContextSignedWitnessPlanAudit.Inspection r=ContextSignedWitnessPlanAudit.inspect(p,x,f,64,WORK);require(!r.audited&&r.output==null,why+": no partial audit receipt");}
 static void mutate(Object target,String field,Object replacement,Attempt check)throws Exception{Field f=target.getClass().getDeclaredField(field);f.setAccessible(true);Object old=f.get(target);try{f.set(target,replacement);check.run();}finally{f.set(target,old);}}
 static void boundaries()throws Exception{
  Snapshot x=bind(true,"!$u local(u,1)&&~off(u,1); !~raw(2);"),a=bind(false,"!$u seed(u,1)&&~blocked(u,1);");List<Snapshot> foreign=Collections.singletonList(a);Plan p=plan(x,foreign);ContextSignedWitnessPlanAudit.Receipt receipt=audit(p,x,foreign);Row first=p.rows.get(0);Seed seed=first.seeds.get(0);Term term=seed.arguments.get(0);Origin other=p.rows.get(2).seeds.get(0).arguments.get(0).origin;
  mutate(seed,"positive",!seed.positive,()->{bad(p,x,foreign,"sign flip");reject(()->ContextSignedWitnessPlanAudit.check(receipt,x,foreign,64,WORK),"historical receipt must freshly reject changed plan");});mutate(term,"origin",other,()->bad(p,x,foreign,"foreign Source with same binder number"));mutate(seed,"proof",new Support(Collections.singleton(a.primary.get(0).source),0),()->bad(p,x,foreign,"foreign singleton Source proof"));mutate(seed,"proof",new Support(Collections.singleton(first.original.source),1),()->bad(p,x,foreign,"nonprimary proof grade"));mutate(p,"rows",Collections.emptyList(),()->bad(p,x,foreign,"lost original row"));mutate(first,"kind",Kind.POSITIVE_WITNESS,()->bad(p,x,foreign,"signed row relabeled positive"));audit(p,x,foreign);
  require(!ContextSignedWitnessPlan.build(x,foreign,1,WORK).planned&&ContextSignedWitnessPlan.build(x,foreign,1,WORK).output==null,"row limit exposes no partial plan");ContextSignedWitnessPlan.Result low=ContextSignedWitnessPlan.build(x,foreign,64,1);require(!low.planned&&low.output==null,"build work stop exposes no signed prefix");ContextSignedWitnessPlanAudit.Inspection stopped=ContextSignedWitnessPlanAudit.inspect(p,x,foreign,64,1);require(!stopped.audited&&stopped.output==null,"audit work stop has no receipt");reject(()->ContextSignedWitnessPlanAudit.check(receipt,x,foreign,64,1),"receipt cannot reuse prior audit under insufficient fresh work");
  require(!ContextSignedWitnessPlan.build(x,Arrays.asList(a,a),64,WORK).planned,"duplicate physical cut rejected");Snapshot group=ContextProductionNativeBinding.trusted("g",Collections.singletonList(a),WORK);require(!ContextSignedWitnessPlan.build(x,Arrays.asList(group,a),64,WORK).planned,"member duplicated through group and independent cut rejected");Snapshot equalText=bind(true,"!$u local(u,1)&&~off(u,1); !~raw(2);");reject(()->ContextSignedWitnessPlanAudit.check(receipt,equalText,foreign,64,WORK),"equal text/new Source identity cannot consume receipt");reject(()->ContextSignedWitnessPlanAudit.check(receipt,x,foreign,63,WORK),"policy mismatch cannot consume receipt");reject(()->ContextSignedWitnessPlanAudit.check(receipt,x,Collections.singletonList(group),64,WORK),"same member/new logical cut cannot consume receipt");
  System.out.println("SIGNED_WITNESS_PLAN_BOUNDARIES signSourceBinderGradeRowTampering=true receiptFreshReplay=true topologyAndPolicyBound=true budgetsAtomic=true noAdmission=true");
 }
}
